------------ define ------------
local DLState = {
    None = 0,
    UnDownloaded = 1,               -- 未下载
    Downloading = 2,                -- 下载中
    DownloadingPaused = 3,          -- 下载中暂停了
    HasDownloadedButNotUsed = 4,    -- 下载了但是没有使用过
    HasDownloadedAndUsed = 5,       -- 下载了并且使用过
    HasDownloadedAndHasUpdate = 6,  -- 已下载并且有更新
}
local DownloadStateKey = "HasVoiceDownload_"
