------------ lifeCycle ------------


function SettingVoiceBtn:CleanProperties()
    self.voiceTag = nil
    self.clickCallback = nil
    self.coProgress = nil
end

function SettingVoiceBtn:InitBtn(voiceTag, voiceDesc, clickCallback)
    self.voiceTag = voiceTag
    self.clickCallback = clickCallback
    self.Txt_Desc.text = voiceDesc

    -- 初始化按钮显示状态
    local downloadState = SettingVoiceMgr:GetVoiceState(voiceTag)
    self:OnVoiceStateChanged(downloadState)

    -- 点击回调
    UIEventProxy.Create(self.RT_ClickArea.gameObject).onPointerClick = Bind(self, self.OnBtnClicked)
end

function SettingVoiceBtn:RefreshName(voiceName)
    self.Txt_Desc.text = voiceName
end

function SettingVoiceBtn:SetSelected(state)
    KTool.SetActive(self.RT_Select, state)
end

function SettingVoiceBtn:OnBtnClicked()
    local downloadState = SettingVoiceMgr:GetVoiceState(self.voiceTag)
    if downloadState == DLState.Downloading then return end

    if not isNull(self.clickCallback)
    and (downloadState == DLState.HasDownloadedButNotUsed or downloadState == DLState.HasDownloadedAndUsed) then
        self.clickCallback()    -- 把其他按钮的选中状态清除
    end

    if downloadState == DLState.UnDownloaded then
        -- 未下载
        SettingVoiceMgr:SetVoiceState(self.voiceTag, DLState.Downloading)
    elseif downloadState == DLState.HasDownloadedButNotUsed then
        -- 已下载，未使用
        KTool.SetActive(self.RT_Select, true)
        SettingVoiceMgr:SetCurrentVoiceTag(self.voiceTag)
        SettingVoiceMgr:SetVoiceState(self.voiceTag, DLState.HasDownloadedAndUsed)
    elseif downloadState == DLState.HasDownloadedAndUsed then
        -- 已下载，使用过
        KTool.SetActive(self.RT_Select, true)
        SettingVoiceMgr:SetCurrentVoiceTag(self.voiceTag)
    elseif downloadState == DLState.HasDownloadedAndHasUpdate then
        -- 已下载，有更新
        SettingVoiceMgr:SetVoiceState(self.voiceTag, DLState.Downloading)
    end
end

--- 下载状态变更的事件
---@param state any
function SettingVoiceBtn:OnVoiceStateChanged(state)
    if state == DLState.UnDownloaded then
        -- 未下载
        self.SImg_BtnState.Status = 2
        KTool.SetActive(self.Txt_DownloadProgress, true)
        local count = SettingVoiceMgr:GetVoiceCount(self.voiceTag)
        self.Txt_DownloadProgress.text = string.format("(%d)", count)
    elseif state == DLState.Downloading then
        -- 下载中
        self.SImg_BtnState.Status = 2
        KTool.SetActive(self.Txt_DownloadProgress, true)
        KTool.SetActive(self.Slider_DownloadProgress, true)
        local downloader = SettingVoiceMgr:DownloadVoice(self.voiceTag)
        self.coProgress = cs_coroutine.start(function()
            while not downloader.IsFinish do
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
                self.Slider_DownloadProgress.value = downloader.Progress
                self.Txt_DownloadProgress.text = string.format("(<color=#00dde6>%d</color>/%d)", checkInt(downloader.Progress * downloader.Count), checkInt(downloader.Count))
            end
        end)
    elseif state == DLState.HasDownloadedButNotUsed then
        -- 下载完成，未使用
        self.SImg_BtnState.Status = 1
        KTool.SetActive(self.RT_RedPoint, true)
    elseif state == DLState.HasDownloadedAndUsed then
        -- 下载完成，已使用
        self.SImg_BtnState.Status = 1
        KTool.SetActive(self.RT_RedPoint, false)
    elseif state == DLState.HasDownloadedAndHasUpdate then
        -- 下载完成，有更新
        self.SImg_BtnState.Status = 1
        KTool.SetActive(self.Txt_DownloadProgress, true)
        local count = SettingVoiceMgr:GetVoiceCount(self.voiceTag)
        self.Txt_DownloadProgress.text = string.format("(%d)", count)
    end
end

--- 下载数量变更的事件
---@param count any
function SettingVoiceBtn:OnVoiceCountChanged(count)
    self.Txt_DownloadProgress.text = string.format("(%d)", count)
end

return SettingVoiceBtn